# פרק 10 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=10
TITLE='פסילת מפלגות'
SUM=['<h3>10.1 פסילת מפלגות</h3><div class="mnhl">\n<h3>א. עקרון חוקיות המנהל — נקודת הפתיחה</h3>\n<p>עיקרון: <strong>אדם פרטי</strong> רשאי לעשות הכול, מלבד הנאסר עליו במפורש. <strong>רשות מנהלית</strong> רשאית לעשות <strong>אך ורק</strong> את מה שהוסמכה לו בחוק. זהו <strong>עקרון חוקיות המנהל</strong>, והבסיס לסוגיה: מהיכן שואבת ועדת הבחירות את הכוח לפסול מפלגה?</p>\n\n<h3>ב. התפתחות היסטורית — מירדור לחקיקת סעיף 7א</h3>\n<ol class="steps">\n<li><strong>ירדור</strong> — ועדת הבחירות פסלה רשימה ששללה את קיום המדינה, בלי סמכות מפורשת. העליון אישר מכוח <em>"נסיבות מיוחדות"</em> ותפיסת ה<strong>דמוקרטיה המתגוננת</strong>.</li>\n<li><strong>ניימן (פרשת כהנא)</strong> — כשנפסלה מפלגה ללא סמכות בחוק, העליון <em>לא</em> אישר — והבהיר שנדרשת הסמכה מפורשת.</li>\n<li><strong>חקיקת ס\' 7א</strong> — הכנסת חוקקה את <strong>סעיף 7א לחוק יסוד: הכנסת</strong>, המסמיך במפורש לפסול ומונה עילות.</li>\n</ol>\n\n<h3>ג. עילות הפסילה — סעיף 7א</h3>\n<div class="law"><span class="ll">עילות סעיף 7א</span>(1) <strong>שלילת קיומה של ישראל כמדינה יהודית ודמוקרטית</strong>; (2) <strong>הסתה לגזענות</strong>; (3) <strong>תמיכה במאבק מזוין</strong> של מדינת אויב או ארגון טרור נגד מדינת ישראל.</div>\n\n<h3>ד. חוק המפלגות וסעיף 5</h3>\n<p>ב-1992 נחקק גם <strong>חוק המפלגות</strong>, שיצר את <strong>רשם המפלגות</strong> והסמיכו שלא לרשום מפלגה. <strong>סעיף 5</strong> מונה ארבע עילות: שלוש כמו בס\' 7א, ועוד עילה — חשש ש<strong>הקמת המפלגה משמשת מסווה לפעולות בלתי חוקיות</strong>.</p>\n<div class="term"><span class="tt">היחס בין הסעיפים</span>העילות זהות, ולכן גם פרשנותן זהה. עם זאת, יש הסוברים שיש לפרש את סעיף 5 בצמצום רב יותר, שכן <em>אי-רישום</em> מפלגה חמור מ<em>אי-אישור</em> השתתפותה — הוא גודע את הקיום הפוליטי בשלב מוקדם.</div>\n\n<h3>ה. פרשנות העילות — הלכת טיבי</h3>\n<p>נקבעה פרשנות <strong>מצמצמת ודבקנית</strong>, למניעת "הפרדוקס הדמוקרטי":</p>\n<ul>\n<li><strong>מאפייני "מדינה יהודית":</strong> רוב יהודי; חגים ומועדים ושבת; עברית כשפה רשמית; מורשת ישראל.</li>\n<li><strong>מאפייני "מדינה דמוקרטית":</strong> ריבונות העם ובחירות; זכויות אדם; הפרדת רשויות; שלטון החוק ורשות שופטת עצמאית.</li>\n</ul>\n\n<h3>ו. העקרונות המנחים לוועדה</h3>\n<ol class="steps">\n<li>האם אחת העילות אכן מתקיימת במטרות/במעשי המפלגה.</li>\n<li>האם העילה היא <strong>היעד המרכזי</strong>, או עניין שולי וטפל.</li>\n<li>האם המפלגה <strong>פועלת בשטח</strong>, או מסתפקת בדיבורים.</li>\n<li>נדרשות <strong>ראיות ברורות וחד-משמעיות</strong> — ודאות, לא אפשרות סבירה.</li>\n<li>ב<strong>ספק</strong> — מאשרים. פסילה פוגעת בזכות לבחור ולהיבחר ובחופש ההתאגדות — <strong>צעד אחרון</strong> למקרים קיצוניים.</li>\n</ol>\n\n<h3>ז. סיכום — נקודות למבחן</h3>\n<ul>\n<li>המקור: עקרון חוקיות המנהל — הרשות פועלת רק מכוח הסמכה.</li>\n<li>התפתחות: ירדור (דמוקרטיה מתגוננת) → ניימן → חקיקת ס\' 7א.</li>\n<li>שלוש עילות (7א): שלילת מדינה יהודית ודמוקרטית · הסתה לגזענות · תמיכה במאבק מזוין.</li>\n<li>ס\' 5 לחוק המפלגות — אותן עילות + מסווה לפעולה בלתי חוקית.</li>\n<li>הלכת טיבי — פרשנות מצמצמת; העקרונות המנחים; פסילה כצעד אחרון (בספק — מאשרים).</li>\n</ul>\n<p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>\n</div>']
CASES=[('בג"ץ 6698/95 קעדאן נ\' מינהל מקרקעי ישראל, פ"ד נד(1) 258 (2000)', '', 'הקצאת מקרקעי מדינה (דרך הסוכנות היהודית) ליהודים בלבד נפסלה כאפליה; נקבע שהשוויון נגזר מערכי ישראל כמדינה יהודית ודמוקרטית.'), ('בג"ץ 5016/96 חורב נ\' שר התחבורה, פ"ד נא(4) 1', '', 'סגירת רחוב בר-אילן בשבת — איזון בין רגשות דתיים לחופש התנועה תוך יישום עקרון המידתיות.'), ("ס' 1א לחוק יסוד: כבוד האדם וחירותו", '', 'עיגון ערכיה של ישראל כמדינה יהודית ודמוקרטית — בסיס לאיזון בין שני המרכיבים.')]
QS=[{'q': 'היכן מעוגנים ערכי "יהודית ודמוקרטית"?', 'o': ['בפקודת הנזיקין', "בס' 1/1א לחוק יסוד: כבוד האדם", 'בחוק החוזים', 'בתקנון הכנסת'], 'c': 1, 'e': 'סעיפי המטרה והעקרונות.'}, {'q': 'מה נפסק בקעדאן?', 'o': ['מותר להקצות קרקע ליהודים בלבד', 'הקצאה ליהודים בלבד היא אפליה פסולה', 'אין שוויון בקרקע', 'דת גוברת'], 'c': 1, 'e': 'בג"ץ 6698/95.'}, {'q': 'מהי גישת ברק ל"יהודית ודמוקרטית"?', 'o': ['עליונות הדמוקרטי', 'עליונות היהודי', 'סינתזה ברמת הפשטה', 'הפרדה מוחלטת'], 'c': 2, 'e': 'קריאה מתואמת של שני המרכיבים.'}, {'q': 'חופש מדת פירושו:', 'o': ['כפיית דת', 'חופש שלא לכפות עליך נורמה דתית', 'איסור פולחן', 'חובת גיוס'], 'c': 1, 'e': 'הצד המשלים לחופש הדת.'}, {'q': 'חורב (5016/96) עסק ב:', 'o': ['קרקע', 'סגירת רחוב בשבת — דת מול תנועה', 'מס', 'חופש ביטוי'], 'c': 1, 'e': 'איזון רגשות דתיים מול חופש התנועה.'}]
